def design(x, j, kind):
    p = x[:, j]
    terms = [np.ones(len(x)), p]
    if kind == 'mixing':
        terms += [x[:, k] for k in range(4) if k != j]
    if kind == 'quadratic':
        terms += [p ** 2]
    if kind.startswith('rational'):
        a = float(kind.split(':')[1])
        terms += [p ** 3 / (1 + a * p ** 2)]
    return np.column_stack(terms)
